return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Spanish (Spain)','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:34+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'es_ES','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lengua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Enrutamiento multilingüe, etiquetas meta SEO y herramientas de contenido AI para WordPress. Combina detección de idioma, enrutamiento de URL, hreflang, descripciones meta y funciones de extracto, meta y traducción impulsadas por IA.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Traducir','Lingua Forge — Quick Translate'=>'Lengua Forge — Traducción rápida','Informative'=>'Informativo','Persuasive'=>'Persuasivo','Storytelling'=>'Narración','Technical'=>'Técnico','Conversational'=>'Conversacional','Permission denied.'=>'Permiso denegado.','Cannot determine target language from slug.'=>'No se puede determinar el idioma de destino a partir del slug.','Invalid post type.'=>'Tipo de publicación no válido.','Invalid or primary language.'=>'Idioma inválido o principal.','Template not found or not stored in the database.'=>'Plantilla no encontrada o no almacenada en la base de datos.','Template has no content.'=>'La plantilla no tiene contenido.','No internal links found to update.'=>'No se encontraron enlaces internos para actualizar.','%d link updated.'=>'%d enlace actualizado.' . "\0" . '%d enlaces actualizados.','No language-specific template parts found to map.'=>'No se encontraron partes de plantilla específicas del idioma para mapear.','No template part references needed updating.'=>'No se necesitan actualizar referencias de partes de plantilla.','%d part reference updated.'=>'Se actualizó la referencia de %d parte.' . "\0" . 'Se actualizaron %d referencias de partes.','Invalid language.'=>'Idioma no válido.','Template part not found or not stored in the database.'=>'Parte de plantilla no encontrada o no almacenada en la base de datos.','Template part has no content.'=>'La parte de la plantilla no tiene contenido.','No navigation references needed updating.'=>'No se necesitan actualizar referencias de navegación.','%d navigation reference updated.'=>'Se actualizó %d referencia de navegación.' . "\0" . 'Se actualizaron %d referencias de navegación.','No AI provider configured.'=>'No se ha configurado ningún proveedor de IA.','Missing pattern name or language.'=>'Falta el nombre del patrón o el idioma.','Pattern not found.'=>'Patrón no encontrado.','Pattern has no content to translate.'=>'El patrón no tiene contenido para traducir.','AI provider returned an empty response.'=>'El proveedor de IA devolvió una respuesta vacía.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Patrón traducido y guardado. Copie el contenido en su publicación CPT mediante el inserto de patrones del editor de bloques o utilícelo como punto de partida para un bloque reutilizable.','Invalid template type.'=>'Tipo de plantilla no válido.','Template "%s" already exists.'=>'La plantilla "%s" ya existe.','"%s" created.'=>'"%s" creado.','Invalid template part.'=>'Parte de plantilla no válida.','Template part "%s" already exists.'=>'La parte de plantilla "%s" ya existe.','"%1$s" created. %2$d template updated.'=>'"%1$s" creado. %2$d plantilla actualizada.' . "\0" . '"%1$s" creado. %2$d plantillas actualizadas.','Page'=>'Página','Single'=>'Individual','Search'=>'Buscar','Search Results'=>'Resultados de búsqueda','Archive'=>'Archivo','Front Page'=>'Página principal','Single: %s'=>'Individual: %s','Single %s'=>'Individual %s','Archive: %s'=>'Archivo: %s','%s Archive'=>'Archivo de %s','No source content found to translate.'=>'No se encontró contenido fuente para traducir.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traducido. Revisa en el Editor del Sitio — los enlaces internos, URLs de navegación y slugs de plantillas no se actualizan automáticamente.','Navigation not found.'=>'Navegación no encontrada.','Navigation has no content to translate.'=>'La navegación no tiene contenido para traducir.','"%1$s %2$s" saved.'=>'"%1$s %2$s" guardado.','Translate page…'=>'Traducir página…','Generate content…'=>'Generar contenido…','AI Behaviour Preset'=>'Preajuste de comportamiento de IA','Custom'=>'Personalizado','Global default (%s)'=>'Predeterminado global (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobrescribe el preajuste de IA para Traducción y Generación de contenido en esta página. Las instrucciones personalizadas a nivel de sitio (Configuración → Comportamiento) siempre se añaden a cada solicitud independientemente de esta selección.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobrescribe el preajuste de IA para Traducción y Generación de contenido en esta página. Todas las demás funciones siempre usan el preajuste global.','Close'=>'Cerrar','Translate missing'=>'Falta traducción','From'=>'De','Retranslate'=>'Retraducir','Translating…'=>'Traduciendo…','Retranslating…'=>'Retraduciendo…','✓ Done'=>'✓ Hecho','Error'=>'Error','Navigation posts are translated via the Router tab, not this button.'=>'Las publicaciones de navegación se traducen a través de la pestaña Router, no con este botón.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Crear traducciones para el tipo de publicación "%s" requiere una integración activa. Asegúrate de que la integración requerida esté instalada y activa.','No %s version found in this translation group.'=>'No se encontró ninguna versión de %s en este grupo de traducciones.','AI Usage'=>'Uso de IA','Today'=>'Hoy','Last 7 days'=>'Últimos 7 días','Last 30 days'=>'Últimos 30 días','All time'=>'Todo el tiempo','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'El consumo de tokens se agrupa por función, proveedor y modelo. Se registra en cada llamada exitosa a la IA; los pings de prueba de conexión se excluyen deliberadamente para no distorsionar los totales. La tabla subyacente agrega diariamente — selecciona una ventana a continuación para verla.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Aún no se ha registrado uso de IA. Una vez que un editor realice una traducción, genere una meta descripción o utilice cualquier otra función de IA, los totales aparecerán aquí.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No se ha registrado uso de IA en la ventana seleccionada (%s). Elige un rango más amplio arriba.','Feature'=>'Función','Provider'=>'Proveedor','Model'=>'Modelo','Requests'=>'Solicitudes','Input tokens'=>'Tokens de entrada','Output tokens'=>'Tokens de salida','Total tokens'=>'Tokens totales','Total'=>'Total','API Keys'=>'Claves API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Las claves se cifran con AES-256-CBC antes de almacenarlas en la base de datos de WordPress. El secreto de cifrado se deriva de tus sales de autenticación de WordPress (wp-config.php), por lo que las claves en texto plano nunca llegan a la base de datos.','API Key'=>'Clave API','Paste your API key…'=>'Pega tu clave API…','✓ Configured'=>'Configurado ✓','✗ Not configured'=>'No configurado ✗','Test connection'=>'Probar conexión','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deja en blanco para mantener la clave existente. Ingresa un nuevo valor para reemplazarla.','Remove stored key'=>'Eliminar clave almacenada','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Esta clave actualmente la proporciona un servidor %s y no puede ser eliminada aquí. Ingresa una nueva clave arriba para sobrescribirla con un valor de la base de datos.','environment variable'=>'variable de entorno','PHP constant'=>'constante de PHP','Alternative (server-side):'=>'Alternativa (lado del servidor):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'También puedes definir claves como constantes o variables de entorno (por ejemplo, en wp-config.php). Esas fuentes se usan automáticamente como respaldo cuando no se almacena una clave en la base de datos.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Para usar un secreto de cifrado personalizado (en lugar del valor derivado wp_salt), añade esto a wp-config.php:','Unknown provider.'=>'Proveedor desconocido.','No API key configured for this provider.'=>'No hay una clave API configurada para este proveedor.','Could not instantiate the provider.'=>'No se pudo instanciar el proveedor.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'El proveedor no devolvió texto. Revisa el registro de errores de WordPress para conocer la razón detallada del fallo.','Behavior'=>'Comportamiento','Block Editor'=>'Editor de bloques','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restringe por defecto dos funciones de Gutenberg para mantener la coherencia editorial en todos los idiomas. Participa aquí si necesitas capacidades completas de Gutenberg / FSE.','Block locking'=>'Bloqueo de bloques','Allow editors to lock individual blocks'=>'Permitir a los editores bloquear bloques individuales','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Vuelve a habilitar canLockBlocks de Gutenberg. Útil para plantillas editoriales que necesitan evitar que los colaboradores muevan o eliminen bloques específicos.','Template mode'=>'Modo de plantilla','Allow Gutenberg template-editing mode on post screens'=>'Permitir modo de edición de plantilla de Gutenberg en pantallas de publicaciones','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Vuelve a habilitar supportsTemplateMode. Esencial en flujos de trabajo de Edición Completa del Sitio donde las anulaciones de plantilla a nivel de publicación son intencionales.','Compliance Preset'=>'Preajuste de cumplimiento','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modo de preservación estricta para contenido legal, regulatorio, médico o técnico. Cuando está activado, cada función de IA usa una temperatura de muestreo baja y añade el apéndice abajo a su prompt del sistema — la terminología, números de artículos, unidades, nombres de marcas y lenguaje regulatorio se preservan exactamente en lugar de parafrasear.','Global AI preset'=>'Preajuste global de IA','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, por función','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Establece el comportamiento predeterminado de IA para todas las funciones en todo el sitio. Las publicaciones individuales pueden sobrescribir esto para Traducción y Generación de Contenido a través del cuadro meta de Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'El modo estándar usa la temperatura ajustada de cada función: Traducción T=0.2 (preciso), Traducción rápida T=0.4, Generador de contenido T=0.6 (creativo). Los otros preajustes aplican una temperatura fija en todas las funciones.','Technical / Scientific instructions'=>'Instrucciones técnicas / científicas','Legal / Compliance instructions'=>'Instrucciones legales / de cumplimiento','Creative / Marketing instructions'=>'Instrucciones creativas / de marketing','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deja en blanco para usar el valor predeterminado incorporado. Borrar una anulación guardada restaura el valor predeterminado en el próximo guardado.','View built-in default'=>'Ver valor predeterminado incorporado','Translation Memory'=>'Memoria de traducción','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Almacena en caché los equivalentes traducidos a nivel de bloque para que el contenido reutilizable (pie de página compartido, barras laterales, acordeones, secciones legales con mucho texto estándar) no tenga que hacer una llamada API cada vez. Cuando está habilitado, el flujo de traducción analiza cada publicación en bloques, busca cada bloque en la caché y envía solo los bloques no en caché a la IA en una solicitud agrupada. Las ediciones del glosario y los cambios en el preajuste de cumplimiento invalidan automáticamente las traducciones en caché afectadas. Ver estadísticas y limpiar la caché en Mantenimiento.','Enable block-level translation cache reuse across posts'=>'Habilitar reutilización de caché de traducción a nivel de bloque en varias publicaciones','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actualmente se omite para publicaciones que usan marcadores de atributos de comentario de bloque (campos wp:details, resumen, etc.) — estos pasan a la ruta de traducción de llamada única existente.','General'=>'General','Light'=>'Ligero','Meta Description, Excerpt Generator'=>'Meta Descripción, Generador de extractos','Quality'=>'Calidad','Translation, Content Generator'=>'Traducción, Generador de contenido','Active Provider'=>'Proveedor activo','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actualmente heredado de la constante %s. Seleccionar un valor aquí lo sobrescribirá.','Models'=>'Modelos','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Las funciones están agrupadas en dos niveles. Ingresa el identificador exacto del modelo para cada nivel y proveedor. Deja un campo en blanco para usar el valor predeterminado incorporado (mostrado como marcador de posición). Solo se llaman los modelos del proveedor activo en tiempo de ejecución — configura los otros con anticipación si planeas cambiar.','active'=>'activo','overridden'=>'sobrescrito','Tip: to reset a model to the built-in default, clear the field and save.'=>'Consejo: para restablecer un modelo al valor predeterminado incorporado, borra el campo y guarda.','Glossary'=>'Glosario','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabla de terminología gestionada por el usuario por par de idiomas. Las entradas se añaden al prompt del sistema de traducción para que la IA utilice términos preferidos de manera consistente — fundamental para vocabulario de dominio ("kWp", "PPA", "punto de interconexión"), nombres de marcas que no deben traducirse y frases regulatorias estandarizadas. Ambos campos de idioma son opcionales: deja en blanco "Idioma fuente" para aplicar la entrada independientemente del idioma desde el que estás traduciendo; deja en blanco "Idioma destino" para aplicarlo a todos los idiomas destino a la vez.','Glossary entry added.'=>'Entrada del glosario añadida.','Glossary entry removed.'=>'Entrada del glosario eliminada.','Could not add entry: source term and target term are required.'=>'No se pudo añadir la entrada: se requieren el término fuente y el término destino.','Could not save the glossary entry.'=>'No se pudo guardar la entrada del glosario.','Source language'=>'Idioma fuente','— Any —'=>'— Cualquiera —','Target language'=>'Idioma destino','— Any target —'=>'— Cualquier destino —','Filter'=>'Filtro','Reset'=>'Restablecer','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'No hay entradas en el glosario que coincidan con el filtro actual. Limpia el filtro para ver todas las entradas, o añade una nueva abajo.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Aún no hay entradas en el glosario. Añade una abajo para empezar a aplicar la terminología en las traducciones.','Source term'=>'Término fuente','Target term'=>'Término destino','Source lang'=>'Idioma fuente','Target lang'=>'Idioma destino','Notes'=>'Notas','any'=>'cualquiera','Delete this glossary entry?'=>'¿Eliminar esta entrada del glosario?','Delete'=>'Eliminar','Add new entry'=>'Añadir nueva entrada','The phrase as it appears in the source text.'=>'La frase tal como aparece en el texto fuente.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Cómo debe aparecer en la traducción. Escribe el mismo valor que el término fuente para indicar a la IA que lo conserve exactamente.','— Any source language —'=>'— Cualquier idioma fuente —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deja en blanco para nombres de marcas y términos independientes del idioma que deben mantenerse sin importar desde qué idioma se traduzca.','— Any target language —'=>'— Cualquier idioma destino —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deja en blanco para aplicar esta entrada a todos los idiomas destino — ideal para nombres de marcas, abreviaturas y términos que deben mantenerse exactamente en cada traducción.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contexto opcional para editores (por ejemplo, "ASIC = Circuito Integrado de Aplicación Específica; conservar en inglés en contextos técnicos").','Add entry'=>'Añadir entrada','Limits'=>'Límites','Authors and above (edit_published_posts)'=>'Autores y superiores (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Colaboradores y superiores — predeterminado (edit_posts)','Editors and above (edit_others_posts)'=>'Editores y superiores (edit_others_posts)','Administrators only (manage_options)'=>'Solo administradores (manage_options)','AI Limits & Security'=>'Límites y Seguridad de IA','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita cuánto puede generar la IA en el sitio y restringe qué roles de usuario pueden activar llamadas pagadas a la IA. Se superpone al límite de tasa por usuario (30 solicitudes / minuto, codificado en duro) que ya protege contra bucles descontrolados de un solo usuario.','Daily request limit'=>'Límite diario de solicitudes','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Techo en toda la web para solicitudes de IA por día UTC (cuenta tanto las traducciones en la barra de herramientas como las revisiones de bloques). El contador se reinicia a la medianoche UTC. Pon en 0 para desactivar el límite.','Minimum role'=>'Rol mínimo','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacidad de WordPress más baja permitida para activar funciones de IA. Restringir esto en sitios con múltiples autores evita que Colaboradores o cuentas de prueba ejecuten llamadas pagadas a la IA. Sobrescribe por función mediante el filtro linguaforge_required_capability.','Translation Limits'=>'Límites de Traducción','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controla cuánto contenido se envía a la IA y cuán grande puede ser la respuesta. Deja en blanco para usar el valor predeterminado incorporado (mostrado como marcador de posición). Aumenta estos valores si las páginas grandes se cortan; bájalos para reducir costos de API.','Model tier'=>'Nivel del modelo','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Calidad (predeterminado — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Ligero (rápido y rentable — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Qué nivel de modelo usar para traducción de página completa. La calidad usa el modelo configurado en la tabla de Modelos arriba y se recomienda para traducciones precisas y de formato largo. Cambia a Ligero solo si la velocidad o el costo son prioritarios y el contenido es corto.','Max output tokens'=>'Tokens máximos de salida','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Número máximo de tokens que la IA puede producir en una sola respuesta de traducción. Si una traducción se corta silenciosamente al final, aumenta este valor. Predeterminado: 16,000.','Max input characters'=>'Caracteres máximos de entrada','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Número máximo de caracteres del contenido de la publicación enviado a la IA. 0 significa sin límite — siempre se envía el contenido completo (recomendado). Establece un valor distinto de cero solo si tu proveedor tiene una ventana de contexto ajustada. Se escribe una advertencia en el registro de errores de PHP cada vez que se recorta el contenido.','Quick Translation'=>' Traducción rápida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traducción rápida se usa en modo fragmento/pedazo — pasajes cortos traducidos a demanda desde la barra de herramientas, editor o popovers de bloques. Utiliza una configuración separada y más ligera que la traducción de página completa para mantener las respuestas rápidas y rentables.','Light (default — fast and cost-effective)'=>'Ligero (predeterminado — rápido y rentable)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Calidad (Soneto / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'El nivel Ligero usa el modelo rápido configurado en la tabla de Modelos arriba (predeterminado: Haiku / Flash). Cambia a Calidad si necesitas la misma precisión de traducción que en modo de página completa para fragmentos.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Número máximo de tokens que la IA puede producir por traducción rápida. Predeterminado: 2 000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Número máximo de caracteres aceptados desde el campo de entrada. Predeterminado: 8 000.','Content Generator'=>'Generador de contenido','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla el presupuesto de tokens y los límites de entrada para la función Generador de contenido de IA. Deja los campos en blanco para usar los valores predeterminados integrados.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Número máximo de tokens que la IA puede producir por ejecución de generación. Aumenta esto si se cortan artículos completos. Predeterminado: 8 192.','Max hints characters'=>'Máx. caracteres de pistas','Maximum characters read from the Hints field. Default: 2 000.'=>'Número máximo de caracteres leídos del campo de Pistas. Predeterminado: 2 000.','Max context characters'=>'Máx. caracteres de contexto','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Número máximo de caracteres del contenido de la publicación existente pasado a la IA como contexto semilla cuando no se proporcionan Pistas. Predeterminado: 6 000.','Maintenance'=>'Mantenimiento','Language Overrides'=>'Sobrescrituras de idioma','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carga archivos .mo compilados para sobrescribir cadenas de plugins de terceros para locales específicos — por ejemplo, una traducción personalizada de VikBooking que use "apartamento" en lugar de "habitación". Los archivos deben seguir la convención de nombres de WordPress: {textdomain}-{locale}.mo (ej. vikbooking-ca.mo). Se almacenan en la carpeta de cargas y sobreviven a actualizaciones del plugin.','Override file uploaded successfully.'=>'Archivo de sobrescritura cargado con éxito.','Override file deleted.'=>'Archivo de sobrescritura eliminado.','No file was selected.'=>'No se seleccionó ningún archivo.','Only .mo files are accepted.'=>'Solo se aceptan archivos .mo.','The upload failed — please try again.'=>'La carga falló — por favor, inténtalo de nuevo.','Could not save the file. Check that the uploads folder is writable.'=>'No se pudo guardar el archivo. Verifica que la carpeta de cargas tenga permisos de escritura.','Invalid filename.'=>'Nombre de archivo inválido.','Security check failed — file path is not permitted.'=>'Error de seguridad — ruta del archivo no permitida.','An unknown error occurred.'=>'Ocurrió un error desconocido.','Text domain / locale'=>'Dominio de texto / local','Files'=>'Archivos','Size'=>'Tamaño','Delete all files for this override (both .mo and .po)?'=>'¿Eliminar todos los archivos de esta sobrescritura (tanto .mo como .po)?','No override files uploaded yet.'=>'Aún no se han cargado archivos de sobrescritura.','Upload .mo file'=>'Cargar archivo .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Solo acepta archivos .mo compilados. El nombre del archivo debe seguir el patrón {textdomain}-{locale}.mo. La carga de un archivo con el mismo nombre que uno existente lo reemplazará.','Upload Override'=>'Cargar Sobrescritura','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copiar a Almacenamiento Seguro','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate almacena sus traducciones personalizadas en wp-content/languages/loco/ — una ubicación que puede ser borrada silenciosamente por una actualización del núcleo de WP, reinstalación del plugin, o si Loco Translate se elimina. Copiar archivos aquí los mueve al directorio Lingua Forge i18n-overrides, que persiste a través de todos esos eventos y se carga automáticamente en cada solicitud.','File copied to safe storage successfully.'=>'Archivo copiado a almacenamiento seguro con éxito.','Source file not found.'=>'Archivo fuente no encontrado.','Could not copy the file. Check that the uploads folder is writable.'=>'No se pudo copiar el archivo. Verifica que la carpeta de cargas tenga permisos de escritura.','Invalid file reference.'=>'Referencia de archivo inválida.','Type'=>'Tipo','✓ In safe storage'=>'✓ En almacenamiento seguro','Copy to safe storage'=>'Copiar a almacenamiento seguro','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Aún no se encuentran archivos personalizados de Loco Translate. Aparecen aquí una vez que guardas una traducción en Loco Translate.','AI Cache'=>'Caché de IA','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge almacena en caché las traducciones generadas por IA, meta descripciones, extractos y contenido generado por publicación para que las entradas sin cambios no vuelvan a activar una llamada API de pago. Las entradas en caché se invalidan automáticamente cuando cambian sus entradas. Limpia la caché manualmente para recuperar espacio en la base de datos, forzar una re-sincronización tras cambiar de proveedor o editar plantillas de instrucciones, o solucionar problemas relacionados con la caché.','AI cache cleared. %d entry was removed.'=>'Caché de IA limpiada. Se eliminó %d entrada.' . "\0" . 'Caché de IA limpiada. Se eliminaron %d entradas.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'¿Borrar todos los resultados en caché de IA? Las solicitudes futuras activarán llamadas API nuevas hasta que se reconstruya la caché.','Clear AI Cache'=>'Borrar caché de AI','Debug Files'=>'Archivos de depuración','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Cuando la depuración de registros está habilitada (a través del interruptor a continuación o definiendo LINGUAFORGE_AI_DEBUG en wp-config.php), las funciones de traducción y traducción de plantillas FSE escriben sus solicitudes y respuestas de AI en disco para solucionar problemas. Usa esta sección para monitorear esa salida y borrarla una vez que tengas lo que necesitas; los archivos pueden crecer rápidamente en páginas grandes. Configura el directorio de destino a través del filtro linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Archivos de depuración borrados. Se eliminó %d archivo.' . "\0" . 'Archivos de depuración borrados. Se eliminaron %d archivos.','Debug logging enabled.'=>'Registro de depuración habilitado.','Debug logging disabled.'=>'Registro de depuración deshabilitado.','Debug logging'=>'Depuración','Write AI prompts and responses to disk for troubleshooting'=>'Escribir solicitudes y respuestas de AI en disco para solucionar problemas','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzado ACTIVADO por la constante LINGUAFORGE_AI_DEBUG en wp-config.php. Elimina esa línea para controlar este interruptor desde aquí.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzado DESACTIVADO por la constante LINGUAFORGE_AI_DEBUG en wp-config.php. Elimina esa línea para controlar este interruptor desde aquí.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Los archivos se almacenan en el directorio a continuación. Útil para diagnosticar problemas de traducción; desactívalo una vez que tengas lo que necesitas para que los archivos no se acumulen. También puedes forzar esto desde wp-config.php con `define( \'LINGUAFORGE_AI_DEBUG\', true );` que anula el interruptor.','Currently:'=>'Actualmente:','✓ Enabled'=>'✓ Activado','✗ Disabled'=>'✗ Desactivado','Directory'=>'Directorio','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra con linguaforge_debug_dir para redirigir la salida de depuración a una ubicación no pública.','.txt file(s) in the directory'=>'.txt archivo(s) en el directorio','Save Debug Setting'=>'Guardar configuración de depuración','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'¿Eliminar todos los archivos .txt en el directorio de depuración? El directorio en sí permanecerá para que futuras escrituras de depuración sigan llegando de manera limpia.','Clear Debug Files'=>'Borrar archivos de depuración','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Caché de traducción por bloque compartido entre publicaciones. Configura en Actividades → Comportamiento. Las estadísticas a continuación muestran lo que está en caché actualmente; borrarlo obliga a que cada bloque se vuelva a traducir en la próxima solicitud (útil después de actualizar modelos o para recuperar espacio en la base de datos).','Translation Memory cleared. %d cached block was removed.'=>'Memoria de traducción borrada. Se eliminó %d bloque en caché.' . "\0" . 'Memoria de traducción borrada. Se eliminaron %d bloques en caché.','Status'=>'Estado','— toggle in Settings → Behavior.'=>'— interruptor en Actividades → Comportamiento.','Cached blocks'=>'Bloques en caché','Cumulative cache hits'=>'Hits acumulados en caché','(avg %.1f hits/block)'=>'(promedio %.1f hits/bloque)','Oldest entry'=>'Entrada más antigua','Newest entry'=>'Entrada más reciente','Approximate size'=>'Tamaño aproximado','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'¿Borrar toda la Memoria de Traducción? Las traducciones futuras reconstruirán la caché a medida que se ejecuten.','Clear Translation Memory'=>'Borrar Memoria de Traducción','Uninstall Behaviour'=>'Desinstalar comportamiento','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla qué sucede cuando un administrador elimina el plugin desde Plugins → Plugins instalados → Eliminar. La configuración del plugin y las cachés de AI siempre se eliminan. Las asignaciones de idioma y las relaciones de traducción se mantienen por defecto para que una desinstalación accidental o una reinstalación puedan continuar donde lo dejaron.','Uninstall setting saved.'=>'Configuración de desinstalación guardada.','Delete content data on uninstall'=>'Eliminar datos de contenido al desinstalar','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'También elimina asignaciones de idioma, relaciones de traducción, meta descripciones, glosario y Memoria de Traducción cuando se desinstala el plugin.','Warning:'=>'Advertencia:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si se marca, desinstalar el plugin eliminará permanentemente todas las asignaciones de idioma, relaciones de traducción, meta descripciones, preajustes por página, el glosario de AI y la Memoria de Traducción para cada publicación en este sitio. Esto no se puede deshacer. No marque esta opción a menos que esté eliminando completamente el soporte multilingüe del sitio.','Save Uninstall Setting'=>'Guardar configuración de desinstalación','Router'=>'Enrutador','Primary language saved.'=>'Idioma principal guardado.','Permalink rules flushed successfully.'=>'Reglas de enlaces permanentes eliminadas con éxito.','Primary Language'=>'Idioma principal','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'El idioma principal siempre se sirve en la raíz de su sitio: sin prefijo en la URL en modo de ruta, sin subdominio de idioma en modo de subdominio. Todos los demás idiomas usan un prefijo de ruta /lang/ (por ejemplo, example.com/de/) o un subdominio de idioma (por ejemplo, de.ejemplo.com), dependiendo de la configuración de estructura de URL a continuación.','Primary language'=>'Idioma principal','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Después de cambiar el idioma principal, actualiza los enlaces permanentes (sección a continuación) para que la enrutación de URL se actualice.','URL structure'=>'Estructura de URL','Path prefix — example.com/de/'=>'Prefijo de ruta — ejemplo.com/de/','Subdomain — de.example.com/'=>'Subdominio — de.ejemplo.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'El modo de subdominio requiere que tu servidor web apunte todos los subdominios de idioma (por ejemplo, de.ejemplo.com) a esta instalación de WordPress. Después de cambiar de modo, actualiza las reglas de enlaces permanentes y borra cualquier caché. Si la URL de inicio incluye www (por ejemplo, www.ejemplo.com), usa el filtro lf_base_domain para establecer el dominio raíz sin www para que los subdominios se construyan correctamente.','Browser language redirect'=>'Redirección por idioma del navegador','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirige a los visitantes a su idioma preferido según la cabecera Accept-Language del navegador','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Cuando está habilitado, los visitantes que visitan por primera vez sin cookie de idioma y sin prefijo de idioma en la URL son redirigidos a la versión en el idioma más cercano. La redirección se omite si el idioma preferido del navegador no está entre los idiomas activos del enrutador. Una vez que un visitante selecciona un idioma mediante el selector, la cookie tiene prioridad y se ignora la cabecera del navegador en futuras visitas.','Save Router Settings'=>'Guardar configuración del enrutador','Flush Permalinks'=>'Actualizar enlaces permanentes','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera las reglas de reescritura de WordPress para que los prefijos de URL, los slugs específicos del idioma y las reescrituras de archivos estén sincronizados. Es necesario después de cambiar el idioma principal o agregar soporte para nuevos idiomas.','Flush Permalink Rules'=>'Actualizar reglas de enlaces permanentes','Active Languages'=>'Idiomas activos','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Idiomas actualmente conocidos por el enrutador (derivados de los paquetes de idioma de WordPress instalados más el idioma principal). Instala paquetes de idioma adicionales en la sección inferior para hacer más idiomas disponibles para el enrutamiento y la traducción.','%d locale pack installed.'=>'%d paquete de idioma instalado.' . "\0" . '%d paquetes de idioma instalados.','Install a Language'=>'Instalar un idioma','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Descarga e instala un paquete de idioma de WordPress directamente desde WordPress.org. Una vez instalado, el idioma estará disponible para el enrutamiento de URL y el flujo de trabajo de traducción AI. La lista de idiomas disponibles se obtiene bajo demanda — haz clic en el botón de abajo para cargarla.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'La instalación de idiomas está deshabilitada en este servidor. La constante DISALLOW_FILE_MODS está configurada en wp-config.php. Instala manualmente los paquetes de idioma mediante WP-CLI: wp language core install de_DE','Load available languages'=>'Cargar idiomas disponibles','— select a language —'=>'— selecciona un idioma —','Install'=>'Instalar','Language Setup'=>'Configuración de idioma','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'No hay idiomas secundarios configurados. Instala un paquete de idioma arriba para habilitar la estructura de plantillas.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecciona un idioma para gestionar sus plantillas FSE, partes de plantilla y menús de navegación.','Forbidden'=>'Prohibido','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'La instalación de idiomas está deshabilitada en este servidor (DISALLOW_FILE_MODS está activado).','Invalid locale code.'=>'Código de idioma no válido.','Language %s installed successfully.'=>'El idioma %s se instaló correctamente.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'La instalación del paquete de idioma falló. El idioma puede ya estar instalado, el código de idioma puede ser incorrecto, o tu servidor puede bloquear las escrituras en archivos.','Navigations'=>'Navegaciones','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traducción de navegación requiere un proveedor de IA activo. Configura una clave API en la pestaña de Claves API.','Navigation'=>'Navegación','Action'=>'Acción','Re-translate'=>'Re-traducir','CPT Block Patterns'=>'Patrones de bloques CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patrones de bloques registrados para tipos de publicaciones personalizadas. Usa el botón de traducir para producir una variante en otro idioma. El contenido traducido se guarda aquí y puede copiarse en cualquier publicación CPT desde el inserter de patrones del editor de bloques o usarse como punto de partida para un patrón sincronizado (Bloque reutilizable).','Pattern'=>'Patrón','Post Types'=>'Tipos de publicaciones','✓ Translation saved'=>'✓ Traducción guardada','View'=>'Ver','Template Parts'=>'Partes de plantilla','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Copias específicas del idioma de las partes de plantilla del tema. Una vez estructuradas, las plantillas se actualizan para hacer referencia a la parte específica del idioma.','Part'=>'Parte','Status / Actions'=>'Estado / Acciones','Fix Links'=>'Corregir enlaces','Fix Nav'=>'Corregir navegación','Create'=>'Crear','Templates'=>'Plantillas','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Plantillas FSE sembradas desde el tema activo. Crea y personaliza en el Editor del sitio.','Actions'=>'Acciones','Fix Parts'=>'Corregir partes','Create missing'=>'Crear faltantes','Translate all'=>'Traducir todo','Fix all parts'=>'Arreglar todas las partes','Fix all links'=>'Arreglar todos los enlaces','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Probando…','✓ Connection OK'=>'✓ Conexión OK','✗ Failed:'=>'✗ Fallido:','No response from provider — check the error log for details.'=>'No hay respuesta del proveedor — revisa el registro de errores para más detalles.','Network error — could not reach the WordPress AJAX endpoint.'=>'Error de red — no se pudo acceder al endpoint AJAX de WordPress.','Loading…'=>'Cargando…','Installing…'=>'Instalando…','✓ Language installed.'=>'✓ Idioma instalado.','✗ Error:'=>'✗ Error:','Creating…'=>'Creando…','✓ All templates created.'=>'✓ Todas las plantillas creadas.','Some templates could not be created.'=>'Algunas plantillas no pudieron ser creadas.','✓ All parts created.'=>'✓ Todas las partes creadas.','Some parts could not be created.'=>'Algunas partes no pudieron ser creadas.','✓ All translated.'=>'✓ Todo traducido.','Some translations failed.'=>'Algunas traducciones fallaron.','Review carefully — links and slugs not updated.'=>'Revisa cuidadosamente — enlaces y slugs no actualizados.','Fixing…'=>'Arreglando…','✓ Links fixed.'=>'✓ Enlaces arreglados.','Some link fixes failed.'=>'Algunos arreglos de enlaces fallaron.','✓ Parts fixed.'=>'✓ Partes arregladas.','Some part fixes failed.'=>'Algunos arreglos de partes fallaron.','✓ Nav refs fixed.'=>'✓ Referencias de navegación arregladas.','Some nav ref fixes failed.'=>'Algunas referencias de navegación no pudieron ser arregladas.','✓ Pattern translated.'=>'✓ Patrón traducido.','Pattern translation failed.'=>'Fallo en la traducción del patrón.','Hide'=>'Ocultar','Built-in preset instructions:'=>'Instrucciones predefinidas incorporadas:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'No hay instrucciones predefinidas — cada función de IA usa sus propios valores predeterminados ajustados. Completa el campo de instrucciones de aviso personalizado a continuación para agregar tus propias reglas para todo el sitio.','Settings'=>'Configuraciones','You do not have permission to manage these settings.'=>'No tienes permiso para gestionar estas configuraciones.','Lingua Forge — Settings'=>'Lingua Forge — Configuraciones','Settings saved.'=>'Configuraciones guardadas.','Save Settings'=>'Guardar configuraciones','Standard'=>'Estándar','Technical / Scientific'=>'Técnico / Científico','Legal / Compliance'=>'Legal / Cumplimiento','Creative / Marketing'=>'Creativo / Marketing','Full Article'=>'Artículo completo','Introduction only'=>'Solo introducción','Structured Outline'=>'Esquema estructurado','Generate Content'=>'Generar contenido','Hints'=>'Pistas','Key points, ideas, or structure to build from…'=>'Puntos clave, ideas o estructura sobre la que construir…','Tone'=>'Tono','Output'=>'Salida','Generate Excerpt'=>'Generar extracto','Generate Meta Description'=>'Generar meta descripción','Translate Content'=>'Traducir contenido','Mode'=>'Modo','Full post'=>'Publicación completa','Translate chunk'=>'Traducir fragmento','Target Language'=>'Idioma de destino','Text to translate'=>'Texto a traducir','Pas